// Откройте Add: измените умножение на params.step — результат изменится во всех вызовах.
// Один исходник, независимое value у каждого подключения.
const component = {
  name: "Counter",
  parameters: {
    type: "object",
    properties: {
      initial: { type: "number", default: 0, label: "Начальное значение" },
      storySource: {
        type: "boolean",
        default: false,
        label: "Менять источник постоянной привязки явно",
      },
      step: { type: "number", default: 1, label: "Множитель изменения" },
    },
  },
  state: {
    type: "object",
    properties: { value: { type: "number", default: 0, label: "Текущее значение" } },
  },
  stateFromParameters: { value: "initial" },
  signals: {
    changed: {
      name: "Значение изменилось",
      payloadSchema: { type: "object", properties: { value: { type: "number" } } },
    },
  },
  methods: {
    add: {
      name: "Добавить",
      parameters: {
        type: "object",
        properties: { amount: { type: "number", default: 1, label: "Количество" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value + args.amount * params.step;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
    read: {
      name: "Прочитать",
      result: { type: "number" },
      run({ state }) {
        return state.value;
      },
    },
    multiply: {
      name: "Умножить",
      parameters: {
        type: "object",
        properties: { factor: { type: "number", default: 2, label: "Множитель" } },
      },
      result: { type: "number" },
      async run({ args, params, state, engine }) {
        const next = state.value * args.factor;
        if (params.storySource) await engine.writeBinding("value", next);
        else state.value = next;
        await engine.emit("changed", { value: state.value });
        return state.value;
      },
    },
  },
};

// Упражнение: замените base * multiplier на base * multiplier + 5.
// Получатель — явная ссылка на Counter, одинаковая логика для очков, монет и отношения.
// Добавьте новый метод bonus с вызовом engine.invoke(refs.counter, "add", {amount: ...}).
const component = {
  name: "Reward",
  parameters: {
    type: "object",
    properties: {
      base: { type: "number", default: 1, label: "Базовая награда" },
      multiplier: { type: "number", default: 1, label: "Множитель награды" },
    },
  },
  references: {
    type: "object",
    properties: {
      counter: { type: "reference", referenceType: "mechanic", label: "Куда начислять · Counter" },
    },
  },
  state: {
    type: "object",
    properties: { awards: { type: "integer", default: 0, label: "Выдано наград" } },
  },
  signals: {
    awarded: {
      name: "Награда выдана",
      payloadSchema: {
        type: "object",
        properties: { amount: { type: "number" }, value: { type: "number" } },
      },
    },
  },
  methods: {
    award: {
      name: "Начислить награду",
      parameters: {
        type: "object",
        properties: { factor: { type: "number", default: 1, label: "Разовый множитель" } },
      },
      result: { type: "number" },
      async run({ args, params, refs, state, engine }) {
        const amount = params.base * params.multiplier * args.factor;
        const value = await engine.invoke(refs.counter, "add", { amount });
        state.awards += 1;
        await engine.emit("awarded", { amount, value });
        return value;
      },
    },
  },
};

// Осмотр предмета явно меняет выбранную сюжетную переменную.
// Упражнение: измените value:true на value:false — ветка чтения письма станет недоступна.
const component = {
  name: "StoryFlag",
  references: {
    type: "object",
    properties: {
      variable: { type: "reference", referenceType: "variable", label: "Сюжетный флаг" },
    },
  },
  methods: {
    interact: {
      name: "Осмотреть и запомнить",
      result: { type: "boolean" },
      async run({ refs, engine }) {
        await engine.operation("sacura.variable.set", { variable: refs.variable, value: true });
        return true;
      },
    },
  },
};

// Два подключения используют один исходник. Условия меняются здесь.
// Упражнение: вместо count > 0 потребуйте count >= 2 или добавьте вызов Reward.award.
// SetLocked(false) меняет только замок. Open — отдельная ожидаемая анимация.
const component = {
  name: "LockedDoor",
  parameters: {
    type: "object",
    properties: {
      InitiallyLocked: { type: "boolean", default: true, label: "Изначально заперта · IsLocked" },
      requiresKey: { type: "boolean", default: false, label: "Разрешать открытие ключом" },
      consumeKey: { type: "boolean", default: false, label: "Расходовать ключ" },
      OpenSeconds: { type: "number", min: 0, default: 0.5, label: "Время открытия, сек" },
    },
  },
  state: {
    type: "object",
    properties: { IsLocked: { type: "boolean", default: true, label: "Заперта · IsLocked" } },
  },
  stateFromParameters: { IsLocked: "InitiallyLocked" },
  references: {
    type: "object",
    properties: {
      inventory: {
        type: "union",
        optional: true,
        label: "Инвентарь",
        variants: [
          { type: "reference", referenceType: "object", label: "Инвентарь объекта" },
          { type: "reference", referenceType: "project", label: "Инвентарь проекта" },
        ],
      },
      key: { type: "reference", referenceType: "item", optional: true, label: "Нужный ключ" },
    },
  },
  signals: { opened: { name: "Дверь открыта", payloadSchema: { type: "object", properties: {} } } },
  methods: {
    setLocked: {
      name: "Задать замок",
      parameters: {
        type: "object",
        properties: { value: { type: "boolean", default: false, label: "Заперта" } },
      },
      result: { type: "boolean" },
      run({ args, state }) {
        state.IsLocked = args.value;
        return state.IsLocked;
      },
    },
    canUnlock: {
      name: "Проверить ключ",
      result: { type: "boolean" },
      async run({ params, refs, engine }) {
        if (!params.requiresKey || !refs.inventory || !refs.key) return false;
        const count = await engine.operation("sacura.inventory.count", {
          owner: refs.inventory,
          item: refs.key,
        });
        return count > 0;
      },
    },
    interact: {
      name: "Взаимодействовать",
      result: { type: "boolean" },
      async run({ state, params, refs, engine, self }) {
        if (state.IsLocked) {
          if (!(await engine.invoke(self, "canUnlock", {}))) {
            await engine.operation("sacura.game.message", { message: "Заперто" });
            return false;
          }
          if (params.consumeKey)
            await engine.operation("sacura.inventory.remove", {
              owner: refs.inventory,
              item: refs.key,
              count: 1,
            });
          await engine.invoke(self, "setLocked", { value: false });
        }
        return await engine.invoke(self, "open", {});
      },
    },
    open: {
      name: "Открыть",
      result: { type: "boolean" },
      async run({ engine, owner, params }) {
        await engine.operation("sacura.door.animate", {
          object: owner,
          open: true,
          seconds: params.OpenSeconds,
        });
        await engine.emit("opened", {});
        return true;
      },
    },
  },
};
